def add_symbols(dimension, basis, vectors):
    """Return a canonical tuple of independent bitmasks spanning the union of the
    existing span (basis) and the given vectors, over GF(2) in the given dimension.

    The result is the reduced row-echelon form of the span, so equal spans in one
    dimension produce identical tuples regardless of insertion order. Tuple length
    is the binary rank. Input sequences are never mutated.
    """
    reduced = []

    def _insert(v):
        # Eliminate pivot bits already present in the basis.
        for r in reduced:
            if v & (r & -r):
                v ^= r
        if v == 0:
            return
        pivot = v & -v
        # Clear this pivot bit from every existing basis vector.
        for i, r in enumerate(reduced):
            if r & pivot:
                reduced[i] = r ^ v
        reduced.append(v)
        reduced.sort(key=lambda x: x & -x, reverse=True)

    for v in basis:
        _insert(v)
    for v in vectors:
        _insert(v)

    return tuple(reduced)

