        self.assertEqual(add_symbols(2, (), [1, 2]), add_symbols(2, (), [3, 1, 2]))

    def test_full_span_standard_basis(self):
        self.assertEqual(add_symbols(3, (), [1, 2, 4]), (4, 2, 1))

    def test_zero_vector_ignored(self):
        self.assertEqual(add_symbols(2, (), [0]), ())

