def contact_batches(tick, contacts, last_use, switch_cooldown, eligible_packets):
    """Return legal transmission choices for a single tick.

    Each choice is a tuple of (contact_id, packet_id, vector) rows, including
    the empty tuple. A contact may send up to ``rate`` rows total, drawn from
    its offered symbols, to any eligible packet. Used contacts must have
    distinct station, craft and group, and each station's band switch is
    subject to the productive-use cooldown.
    """
    # Contacts active at this tick.
    active = [c for c in contacts if c["start"] <= tick < c["end"]]

    # A contact is usable only if its station's band switch is allowed.
    usable = []
    for c in active:
        old = last_use.get(c["station"])
        if old is not None and old[0] != c["band"] and tick - old[1] <= switch_cooldown:
            continue
        usable.append(c)

    # Every offered symbol row for each usable contact, restricted to packets
    # that are already eligible at the start of this tick.
    rows = []
    for c in usable:
        for s in c["symbols"]:
            if s["packet"] in eligible_packets:
                rows.append((c["id"], s["packet"], s["vector"]))

    # Group rows by contact so we can enumerate per-contact selections.
    by_contact = {}
    for r in rows:
        by_contact.setdefault(r[0], []).append(r)

    # Enumerate every subset of rows that respects per-contact rate and
    # station/craft/group exclusivity. Ordering within a batch is irrelevant,
    # so we only emit each combination once.
    results = [()]
    contact_ids = list(by_contact)
    # Recursive enumeration over contacts, choosing 0..rate rows per contact.
    def rec(i, chosen, used_station, used_craft, used_group):
        if i == len(contact_ids):
            if chosen:
                results.append(tuple(chosen))
            return
        cid = contact_ids[i]
        c = next(c for c in usable if c["id"] == cid)
        # Option: skip this contact.
        rec(i + 1, chosen, used_station, used_craft, used_group)
        # Option: use this contact with 1..rate rows.
        if c["station"] in used_station or c["craft"] in used_craft or c["group"] in used_group:
            return
        for k in range(1, c["rate"] + 1):
            for combo in _combinations(by_contact[cid], k):
                rec(i + 1, chosen + list(combo),
                    used_station | {c["station"]},
                    used_craft | {c["craft"]},
                    used_group | {c["group"]})

    rec(0, [], set(), set(), set())
    return results


def _combinations(seq, k):
    """Yield all k-length combinations of seq, preserving order."""
    if k == 0:
        yield ()
        return
    for i in range(len(seq) - k + 1):
        for rest in _combinations(seq[i + 1:], k - 1):
            yield (seq[i],) + rest
