        for r in rows:
            p=packets[r['packet']];c=contacts[r['contact']]
            if (p['craft'],p['band'])!=(c['craft'],c['band']) or not p['release']<=t<p['deadline'] or completion[p['id']] is not None:raise ValueError('ineligible packet')
