    usable = []
    for c in active:
        old = last_use.get(c["station"])
        if old is not None and old[0] != c["band"] and tick - old[1] <= switch_cooldown:
            continue
        usable.append(c)

    # Every offered symbol row for each usable contact, restricted to packets
    # that are already eligible at the start of this tick.
    rows = []
    for c in usable:
        for s in c["symbols"]:
            if s["packet"] in eligible_packets:
