from engines.analysis.coding_basis import add_symbols
from engines.analysis.contact_policy import contact_batches


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    q = payload["request"]
    packets = {p["id"]: p for p in q["packets"]}
    contacts = q["contacts"]
    cooldown = q["switch_cooldown"]
    horizon = max(c["end"] for c in contacts)

    # Topological order of packets by prerequisite DAG.
    order = []
    seen = set()

    def visit(pid):
        if pid in seen:
            return
        seen.add(pid)
        for dep in packets[pid]["requires"]:
            visit(dep)
        order.append(pid)

    for pid in packets:
        visit(pid)

    # State: for each packet, its current canonical span (tuple of bitmasks).
    # completion maps packet -> tick of completion (t+1) or None.
    # last_use maps station -> (band, tick) of last actually used contact.
    # We search over the whole horizon with memoization on a canonical state.
    best = None

    def canonical_state(spans, completions, last_use, tick):
        # Spans are already canonical tuples; completions and last_use are dicts.
        return (
            tuple(sorted((pid, spans[pid]) for pid in packets)),
            tuple(sorted((pid, completions[pid]) for pid in packets)),
            tuple(sorted(last_use.items())),
            tick,
        )

    memo = {}

    def search(tick, spans, completions, last_use):
        nonlocal best
        if tick > horizon:
            return
        key = canonical_state(spans, completions, last_use, tick)
        if key in memo:
            return
        memo[key] = True

        # Determine eligible packets at start of this tick.
        eligible = set()
        for pid in order:
            p = packets[pid]
            if completions[pid] is not None:
                continue
            if not (p["release"] <= tick < p["deadline"]):
                continue
            if any(completions[d] is None or completions[d] > tick for d in p["requires"]):
                continue
            eligible.add(pid)

        # Evaluate current score as a candidate (final ranks).
        ranks = {pid: len(spans[pid]) for pid in packets}
        decoded = [pid for pid in packets if completions[pid] is not None]
        score = {
            "priority": sum(packets[pid]["priority"] for pid in decoded),
            "count": len(decoded),
            "rank": sum(ranks.values()),
        }
        # Track best by lexicographic score.
        if best is None or _better(score, best["score"]):
            best = {
                "score": score,
                "ranks": ranks,
                "completions": dict(completions),
                "transmissions": list(_transmissions),
                "contacts": list(_contacts),
            }

        # Enumerate legal batches for this tick.
        for batch in contact_batches(tick, contacts, last_use, cooldown, eligible):
            # Apply the batch: update spans, completions, last_use.
            new_spans = {pid: spans[pid] for pid in packets}
            new_completions = dict(completions)
            new_last_use = dict(last_use)
            used_contacts = set()
            for (cid, pid, vec) in batch:
                used_contacts.add(cid)
                new_spans[pid] = add_symbols(packets[pid]["dimension"], new_spans[pid], [vec])
            # Update completions for packets that just reached full rank.
            for pid in order:
                if new_completions[pid] is None and len(new_spans[pid]) == packets[pid]["dimension"]:
                    new_completions[pid] = tick + 1
            # Update station history for used contacts.
            for cid in used_contacts:
                c = next(c for c in contacts if c["id"] == cid)
                new_last_use[c["station"]] = (c["band"], tick)
            # Record transmissions and contacts for this branch.
            _transmissions.extend(
                {"tick": tick, "contact": cid, "packet": pid, "vector": vec}
                for (cid, pid, vec) in batch
            )
            _contacts.extend({"tick": tick, "contact": cid} for cid in used_contacts)
            search(tick + 1, new_spans, new_completions, new_last_use)
            # Backtrack.
            del _transmissions[len(_transmissions) - len(batch):]
            del _contacts[len(_contacts) - len(used_contacts):]

    _transmissions = []
    _contacts = []
    spans = {pid: () for pid in packets}
    completions = {pid: None for pid in packets}
    search(0, spans, completions, {})

    return {
        "score": best["score"],
        "packets": [
            {"id": pid, "rank": best["ranks"][pid], "completion": best["completions"][pid]}
            for pid in packets
        ],
        "contacts": best["contacts"],
        "transmissions": best["transmissions"],
    }


def _better(a, b):
    return (a["priority"], a["count"], a["rank"]) > (b["priority"], b["count"], b["rank"])


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)
