    def test_rank_one_duplicate(self):
        # SPEC: repeats do NOT increase rank.
        self.assertEqual(add_symbols(2, (), [1, 1]), (1,))

    def test_canonical_independent_of_order(self):
        # SPEC: equal spans have identical tuples regardless of insertion order.
        self.assertEqual(add_symbols(2, (), [1, 2]), add_symbols(2, (), [3, 1, 2]))

